const crypto = require('crypto');
const item = $input.first();
const h = item.json.headers || {};
// Verify the exact bytes Convex signed, not a re-serialised copy.
const raw = item.binary?.data
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')
  : JSON.stringify(item.json.body);
const ts = h['x-lendloop-timestamp'] || '';
const sig = String(h['x-lendloop-signature'] || '');
const expected = crypto.createHmac('sha256', $env.CONVEX_TO_N8N_SECRET).update(`${ts}.${raw}`).digest('hex');
const fresh = Math.abs(Date.now() - Number(ts)) < 5 * 60 * 1000;
const valid = fresh && sig.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
if (!valid) return [{ json: { valid: false } }];
const p = JSON.parse(raw);
const seen = $getWorkflowStaticData('global').keys || [];
return [{ json: { valid: true, duplicate: seen.includes(p.idempotencyKey), ...p } }];

// Mock channel: one log line per message. Swap for Send Email / Slack / Discord in production.
const p = $input.first().json;
if (p.duplicate) return [{ json: { ...p, delivered: false } }];
const range = `${p.startDate} to ${p.endDate}`;
const text = {
  requested: `someone asked to borrow your ${p.tool} (${range}). Open LendLoop to approve or decline.`,
  cancelled: `the request for your ${p.tool} (${range}) was cancelled.`,
  approved: `your request for the ${p.tool} (${range}) was approved.`,
  declined: `your request for the ${p.tool} (${range}) was declined.`,
  returned: `thanks for returning the ${p.tool}.`,
}[p.event];
if (!text) throw new Error(`Unknown event: ${p.event}`);
const message = `Hi ${p.recipient.name}, ${text}`;
console.log(`[lendloop] to=${p.recipient.email ?? 'no-email'} ${message}`);
return [{ json: { ...p, delivered: true, channel: 'mock-log', message } }];

// Only after delivery succeeds, so a failed run can be retried by Convex.
const p = $input.first().json;
const data = $getWorkflowStaticData('global');
if (p.delivered) data.keys = [...(data.keys || []), p.idempotencyKey].slice(-500);
return [{ json: { ok: true, duplicate: p.duplicate } }];
